// ---- Validar el mensaje ----
const body = $input.first().json.body || $input.first().json;
const raw = (body.message || '').toString();
const sessionId = body.sessionId || null;
const lang = (body.lang || 'es').toLowerCase().startsWith('en') ? 'en' : 'es';
const trimmed = raw.trim();

const MSG = {
  es: { empty: 'Escribime tu consulta primero \ud83d\ude42', tooLong: 'Tu mensaje es un poco largo, \u00bfpod\u00e9s resumirlo?' },
  en: { empty: 'Type your question first \ud83d\ude42', tooLong: 'Your message is a bit long, could you shorten it?' },
};

let valid = true;
let reply = null;

if (!trimmed) {
  valid = false;
  reply = MSG[lang].empty;
} else if (trimmed.length > 400) {
  valid = false;
  reply = MSG[lang].tooLong;
}

const clean = trimmed.replace(/<[^>]*>/g, '');

return [{ json: { valid, reply, message: clean, sessionId, lang } }];

// ---- Clasificar intenci\u00f3n (misma l\u00f3gica que el widget) ----
const text = ($json.message || '').toLowerCase();
const lang = $json.lang || 'es';

const CLINICAL_KEYWORDS = ['dosis','cuanta insulina','cu\u00e1nta insulina','me pongo','sintoma','s\u00edntoma','me siento mal','hipoglucemia','hiperglucemia','desmay','emergencia','me duele','dolor','dose','dosage','how much insulin','symptom','i feel sick','hypoglycemia','hyperglycemia','passed out','emergency','it hurts','pain'];

const TOPICS = [
  { id: 'registro', keywords: ['registrar','registro','cargar','carga','anotar','glucosa','insulina','comida','carbohidr','log','logging','record','entry','glucose','insulin','meal','carb'],
    reply: { es: 'Pod\u00e9s registrar glucosa, insulina, comidas y actividad desde el bot\u00f3n \"+\" en la pantalla principal. Se guarda en segundos y suma puntos a tu racha.', en: 'You can log glucose, insulin, meals and activity from the \"+\" button on the main screen. It saves in seconds and adds points to your streak.' },
    options: { es: ['\u00bfC\u00f3mo sumo puntos?', '\u00bfD\u00f3nde veo mis reportes?'], en: ['How do I earn points?', 'Where can I see my reports?'] } },
  { id: 'puntos', keywords: ['punto','puntos','nivel','logro','recompensa','racha','estrella','point','points','level','achievement','reward','streak','star'],
    reply: { es: 'Gan\u00e1s puntos por cada registro diario completo. Los puntos suben tu nivel y desbloquean logros \u2014 nunca califican tus valores de glucosa, solo tu constancia.', en: 'You earn points for every complete daily log. Points level you up and unlock achievements \u2014 they never grade your glucose values, only your consistency.' },
    options: { es: ['\u00bfC\u00f3mo registro mis datos?', '\u00bfQu\u00e9 incluye cada plan?'], en: ['How do I log my data?', 'What\'s included in each plan?'] } },
  { id: 'reportes', keywords: ['reporte','grafico','gr\u00e1fico','tiempo en rango','tir','estadistica','estad\u00edstica','historial','report','chart','graph','time in range','statistics','history'],
    reply: { es: 'En la secci\u00f3n de Reportes vas a encontrar tu Tiempo en Rango (TIR) y el cruce de glucosa vs. insulina, listos para compartir en tu consulta.', en: 'In the Reports section you\'ll find your Time in Range (TIR) and the glucose vs. insulin comparison, ready to share at your appointment.' },
    options: { es: ['Hablar con alguien del equipo'], en: ['Talk to someone on the team'] } },
  { id: 'compartir_datos', keywords: ['datos al medico','datos al m\u00e9dico','enviar datos','compartir datos','mandar datos','codigo qr','c\u00f3digo qr','send data','share data','data to my doctor','data to the doctor','doctor scan','qr code'],
    reply: { es: 'Escane\u00e1 el c\u00f3digo QR que te comparte tu m\u00e9dico y tus datos se env\u00edan autom\u00e1ticamente \u2014 no hace falta exportar ni mandar nada a mano.', en: 'Scan the QR code your doctor shares with you and your data is sent automatically \u2014 no need to export or send anything by hand.' },
    options: { es: [], en: [] } },
  { id: 'tratamiento', keywords: ['tratamiento','rango','hipo','hiper','target','dosis basal','esquema','treatment','range','low target','high target','basal dose','regimen'],
    reply: { es: 'En \"Tratamiento\" configur\u00e1s tus rangos objetivo (hipo, target, hiper) junto con tu profesional de salud. Yo no puedo definir esos valores por vos.', en: 'In \"Treatment\" you set your target ranges (low, target, high) together with your healthcare professional. I can\'t set those values for you.' },
    options: { es: ['Hablar con alguien del equipo'], en: ['Talk to someone on the team'] } },
  { id: 'telemedicina', keywords: ['telemedicina','turno','consulta','medico','m\u00e9dico','doctora','doctor','videollamada','cita','telehealth','appointment','video call','physician'],
    reply: { es: 'Pod\u00e9s agendar una consulta de telemedicina desde la secci\u00f3n \"Mi equipo\". Vas a ver los horarios disponibles de tu profesional asignado.', en: 'You can schedule a telehealth visit from the \"My team\" section. You\'ll see the available times for your assigned professional.' },
    options: { es: ['Hablar con alguien del equipo'], en: ['Talk to someone on the team'] } },
  { id: 'planes', keywords: ['plan','precio','premium','gratis','suscripcion','suscripci\u00f3n','pagar','costo','price','pricing','free','subscription','pay','cost'],
    reply: { es: 'El plan gratuito incluye registro y reportes b\u00e1sicos por 60 d\u00edas. El plan Premium suma telemedicina ilimitada y reportes avanzados.', en: 'The free plan includes basic logging and reports for 60 days. The Premium plan adds unlimited telehealth and advanced reports.' },
    options: { es: ['Hablar con alguien del equipo'], en: ['Talk to someone on the team'] } },
  { id: 'familia', keywords: ['familia','padre','madre','cuidador','conectar','vincular','compartir acceso','family','parent','caregiver','connect','link','share access'],
    reply: { es: 'Gener\u00e1 un c\u00f3digo QR desde la app y pedile a tu familiar que lo escanee desde la suya \u2014 el v\u00ednculo se crea autom\u00e1ticamente, sin pasos extra.', en: 'Generate a QR code from the app and have your family member scan it from theirs \u2014 the link is created automatically, no extra steps.' },
    options: { es: ['\u00bfC\u00f3mo registro mis datos?'], en: ['How do I log my data?'] } },
  { id: 'soporte', keywords: ['soporte','ayuda humana','hablar con alguien','contacto','persona','humano','support','human help','talk to someone','contact','human'],
    reply: { es: 'Te dejo el contacto de soporte: soporte@sugar.coach. Un humano te responde a la brevedad.', en: 'Here\'s our support contact: soporte@sugar.coach. A person will get back to you shortly.' },
    options: { es: [], en: [] } },
];

const TOP_LEVEL_OPTIONS = {
  es: ['C\u00f3mo registrar mis datos','Puntos y logros','Ver mis reportes','C\u00f3mo enviar datos al m\u00e9dico','C\u00f3mo vincular a mi familia','Planes y precios','Hablar con soporte'],
  en: ['How to log my data','Points and achievements','View my reports','How to send data to my doctor','How to link my family','Plans and pricing','Talk to support'],
};

let result;
if (CLINICAL_KEYWORDS.some(k => text.includes(k))) {
  result = {
    intent: 'clinical_redirect',
    reply: lang === 'en'
      ? "I can't give medical advice \u2014 that's something your healthcare team needs to handle. I can help with how to use the app, or connect you with your team."
      : 'No puedo darte indicaciones m\u00e9dicas \u2014 eso lo tiene que ver tu equipo de salud. Puedo ayudarte con c\u00f3mo usar la app, o coordinar que hables con tu equipo.',
    options: lang === 'en' ? ['Talk to someone on the team', 'How do I log my data?'] : ['Hablar con alguien del equipo', '\u00bfC\u00f3mo registro mis datos?'],
  };
} else {
  const topic = TOPICS.find(tp => tp.keywords.some(k => text.includes(k)));
  if (topic) {
    result = { intent: topic.id, reply: topic.reply[lang], options: topic.options[lang] };
  } else {
    result = {
      intent: 'unknown',
      reply: lang === 'en' ? "I'm not sure I understood. Pick an option, or tell me in other words:" : 'No estoy seguro de haber entendido. Eleg\u00ed una opci\u00f3n, o contame con otras palabras:',
      options: TOP_LEVEL_OPTIONS[lang],
    };
  }
}

return [{ json: { ...result, sessionId: $json.sessionId, message: $json.message, lang } }];
